import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Less is More: Data-Efficient Adaptation for Controllable Text-to-Video Generation","description":"","frontmatter":{"title":"Less is More: Data-Efficient Adaptation for Controllable Text-to-Video Generation","arxiv":"2511.17844","date":"2025-11-21","authors":"Shihan Cheng, Nilesh Kulkarni, David Hyde, Dmitriy Smirnov","categories":"cs.CV, cs.AI","topics":"物理感知视频生成, 可控生成, 数据高效微调","outline":[2,2]},"headers":[],"relativePath":"papers/2511.17844.md","filePath":"papers/2511.17844.md","lastUpdated":null}'),e={name:"papers/2511.17844.md"};function l(i,s,r,m,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="less-is-more-data-efficient-adaptation-for-controllable-text-to-video-generation" tabindex="-1">Less is More: Data-Efficient Adaptation for Controllable Text-to-Video Generation <a class="header-anchor" href="#less-is-more-data-efficient-adaptation-for-controllable-text-to-video-generation" aria-label="Permalink to &quot;Less is More: Data-Efficient Adaptation for Controllable Text-to-Video Generation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2511.17844" target="_blank" rel="noreferrer">2511.17844</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-11-21</td></tr><tr><td><strong>作者</strong></td><td>Shihan Cheng, Nilesh Kulkarni, David Hyde, Dmitriy Smirnov</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>用几何原语级的廉价合成数据加「backbone LoRA 吸收域偏移、并行 cross-attention 只学物理效应」的分工，再在推理时丢掉浅层 LoRA，把快门/光圈/色温做成连续可控且不损伤底模先验的控制轴。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/physics-aware">物理感知视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>给大规模 T2V 模型加一个新的控制轴，标准做法是收一批带标注的高保真数据然后微调。对相机内参这类物理量——快门速度决定运动模糊，光圈决定景深，色温决定色调——这条路几乎走不通：现实中很难拿到同一场景下只有快门变化、其余全部固定的成对视频。</p><p>论文提出的方案是完全放弃真实感：用稀疏、低保真的程序化合成数据（几何原语在纯色背景上匀速运动）来学这些控制。反直觉的结论是，这样不但能学会，效果还<strong>优于</strong>在照片级真实数据上微调的模型。作者把原因归结为一个容易被忽略的机制——照片级数据虽然看起来是更高保真的选择，却会污染 backbone 的预训练先验，引发灾难性遗忘和「内容坍缩」。</p><p>这件事的价值超出相机参数本身。它挑战了「微调数据应当尽可能贴近目标分布」这条默认信条，并给出了一个可操作的替代原则：微调数据集应当尽可能<strong>解耦</strong>，而不是尽可能真实。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>可控生成方面，ControlNet、T2I-Adapter 已经把深度、掩码、草图、框、分割图这类空间条件做得很成熟，视频侧的扩展集中在相机位姿与轨迹（CameraCtrl、MotionCtrl、ViewCrafter）。这些都是空间条件，不解决低维物理标量。图像域里 Bokeh Diffusion、Generative Photography、CamEdit 确实研究了相机感知的合成与编辑，但图像设定不涉及时序一致性与可控运动，无法直接迁移到 T2V。CSaT 用 token 化的相机设置做隐式控制，仍然是数据密集的。核心障碍很实在：大规模、带精确物理相机参数标注的视频数据集根本不存在。</p><p>从合成与稀疏数据学习这一线，已有工作表明简单合成数据能孕育强表示（Tian 等）、程序化生成视频可以媲美自然视频预训练（Yu 等）、合成 3D 环境为光流/跟踪/深度提供精确标签。这些结果暗示运动先验不必依赖复杂自然数据，但没人把它用在「往预训练 T2V 里注入物理控制」上。</p><p>评测方面缺口更明确：FVD、CLIP Score、X-CLIP、VQA Score、VBench 各自覆盖分布相似度、文本对齐、质量与时序一致，Shuttleworth 等人提出了分析 LoRA 与全量微调如何重塑权重的谱工具。但<strong>没有任何指标量化微调数据本身的复杂度，以及它对 backbone 漂移的影响</strong>。这正是作者要补的方法论空白。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>先看一个既有事实：大量成功的专用视频模型都是「大 foundation 模型 + 小规模任务数据微调」。这暗示预训练已经把大量有用先验编码进潜表示里，后训练的作用更像是把已有属性「哄」出来，而不是外推出新领域。</p><p>如果这个判断成立，那么对于运动模糊、散景这类<strong>光学效应</strong>，模型其实早就见过无数带运动模糊的视频、无数浅景深的镜头。缺的不是知识，是一个能连续调节它的旋钮。而学一个旋钮，需要的数据只要在这条控制轴上有干净的变化即可，场景内容是什么完全无所谓。</p><p>但用完全不真实的数据微调必然带来域偏移，模型会往合成风格漂。这里作者做了一个关键的责任划分：让一个标准 LoRA 去吸收域偏移，让一个独立的 cross-attention adapter 专门学控制信号。两者分工明确，各管一摊。</p><p>最后一步是推理时的操作。既然 LoRA 的职责只是「吸收合成域的偏移」，那么在推理时它就是纯粹的负担——把它从不带 conditional adapter 的层里丢掉，就能恢复原始先验又保住控制能力。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>预训练模型已经知道什么是运动模糊，微调只需要给它一个旋钮，不需要教它这个概念。因此微调数据的复杂度是纯粹的成本——内容越丰富，模型越容易记住内容而不是效应，把 backbone 的通用表示挤掉。用几何原语这种语义近乎为零的数据，效应轴上的变化就成了数据里唯一的信息，adapter 别无选择只能学到它。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>架构有两处改动。<strong>解耦条件模块</strong>：标量条件归一化到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">c</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>，经小 MLP 得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">e</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">cond</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">MLP</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">cond</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">c</span><span class="mclose">)</span></span></span></span>，再通过一路专用 cross-attention 注入，与文本 cross-attention 并行；这个 adapter 只插在原模型 transformer blocks 最深的三分之一。对来自视频潜变量的 query <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">q</span></span></span></span>，该 block 的输出是文本条件 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">text</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与属性条件 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">cond</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的线性组合。<strong>Backbone LoRA</strong>：训练时注入到所有 DiT block；推理时把不带 conditional adapter 的层（浅层三分之二）的 LoRA 权重丢弃，只保留最深三分之一——这就是 Decoupled Inference。</p><p>数据构造以快门速度为例：给定采样标量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 与一个随机场景，用一个简易 2D 物理渲染器在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">512</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">512</span></span></span></span> 画布上放 1–3 个彩色几何原语（圆、方、三角、星），匀速运动、边界弹性反射。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span></span></span></span> 通过中心化对数映射变成有效帧率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm">FPS</span></span><span class="mopen">(</span><span class="mord mathnormal">c</span><span class="mclose">)</span></span></span></span>，曝光时长设为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1/</span><span class="mord"><span class="mord mathrm">FPS</span></span><span class="mopen">(</span><span class="mord mathnormal">c</span><span class="mclose">)</span></span></span></span>；每一输出帧对 32 个解析预测的子帧做时域平均得到运动模糊。关键在于同一场景下所有快门取值共享完全相同的轨迹与背景，沿控制轴变化的只有模糊强度。光圈用 Blender 渲 3D 景深（2–4 个刚体分布在不同深度，前景物体锁焦，只改 f 值），色温用基于 Mired 的 Kelvin-to-RGB 白平衡变换。</p><p>采样策略是金字塔式：把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 分成 5 层，各层取 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">9</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">7</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">3</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">25</span></span></span></span> 个抖动采样的标量，每层生成 6 个随机场景，合计 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">6</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">25</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">150</span></span></span></span> 个训练样本。相比穷举的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">30</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">150</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">4500</span></span></span></span> 组合，规模缩小 30 倍，同时保持控制区间的均匀覆盖。</p><p>对照用的「照片级」数据集每个效应只有一个场景：快门用 240fps 高速视频做时域累加，光圈用 BokehMe 处理一张复杂前景图，色温对一张自然户外场景做物理白平衡变换，各取 7 个标量条件。</p><p>训练在 A100 80GB 上用 Wan2.1-T2V-14B 做 backbone，bf16，全局 batch 4，30-shot 合成数据约 18000 步，双卡约一天；4 个条件 adapter token，adapter 嵌入维 256，LoRA rank 32，adapter gate 固定 0.5，学习率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">2</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8141em;"></span><span class="mord">1</span><span class="mord"><span class="mord">0</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8141em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">−</span><span class="mord mtight">5</span></span></span></span></span></span></span></span></span></span></span></span>，AdamW。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>论文的分析工具比方法本身更值得读，核心是三个数据无关的谱诊断。</p><p><strong>漂移速率。</strong> FEP（Fast Evaluation Protocol）用单步去噪从固定潜种子生成 4 帧，在 CLIP 空间与原始 backbone 对比：SSF 是逐 prompt 余弦相似度的均值（接近 1 表示语义先验基本没变），SS-FD 是两个嵌入分布之间的 Fréchet 距离。由此定义分布漂移速率</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">drift</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.363em;vertical-align:-0.936em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.427em;"><span style="top:-2.314em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span><span class="mopen">(</span><span class="mord text"><span class="mord">steps</span></span><span class="mclose">)</span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.677em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0379em;">δ</span><span class="mopen">(</span><span class="mord text"><span class="mord">SS-FD</span></span><span class="mclose">)</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.936em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mord">.</span></span></span></span></span></p><p>这个量的巧妙之处在于它把「数据集复杂度」这个难以直接测量的概念，操作化成「它对模型造成的改变速度」。低复杂度数据（2D 原语）<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">drift</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 低，高复杂度数据（照片级场景）<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">drift</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 高。单靠这个量还不够——高漂移可能是良性适配也可能是灾难性遗忘，所以需要与 SVP 阶段的 X-CLIP、VQA 交叉参照：终值高就是良性，崩掉就是恶性。</p><p><strong>入侵维度。</strong> 借用 Shuttleworth 等人的方法，对原始权重 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pre</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 与适配后权重 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">lora</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pre</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord">Δ</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">lora</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 分别做 SVD，若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">lora</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 中出现一个高排名奇异向量，与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9694em;vertical-align:-0.2861em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">pre</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span> 中所有向量的余弦相似度都低于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ϵ</span></span></span></span>，就记为一个 intruder。入侵维度多是灾难性遗忘的数学指纹，少则说明适配是非破坏性的。</p><p><strong>条件信号的有效秩。</strong> 取强条件 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>，计算 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">cond</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 重排成矩阵后的奇异值谱。直觉是：运动模糊这类物理效应本质上是低维的，不该需要高维特征空间。若谱迅速衰减、有效秩低，说明 adapter 学到的是效应本身；若谱衰减缓慢、且形态与内容信号 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">text</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 相似，说明它记住的是训练数据的内容。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>第一组实验隔离数据内容的影响。每个相机参数各训两个模型：一个用单个合成场景，一个用单个照片级场景，各取 7 个标量条件，其余完全相同，用 FEP 在 VBench 的 800 条 prompt 上监测。结论清晰：照片级数据的 FEP 分数随训练步数变化明显更快，即 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">drift</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 高得多；而 SVP 验证揭示了这种漂移的性质——照片级模型的 X-CLIP 与 VQA 双双崩塌，属于恶性遗忘，合成模型则与 baseline 持平。可视化给出了直观对应：照片级模型在训练中越来越像在<strong>复制训练场景</strong>，细节、纹理、整体色调都往训练图像上漂，表现为语义漂移、纹理坍缩与颜色幻觉。</p><p>第二组实验验证推理策略。在完整金字塔合成数据上训练后，比较 Decoupled Inference 与 Full-LoRA Inference，用 96 条高运动 prompt、50 步去噪、49 帧的 SVP 评。Decoupled 在三个控制上都更接近 baseline：X-CLIP 基线 25.390，Decoupled 为 25.587 / 25.595 / 25.595，Full-LoRA 为 25.295 / 25.181 / 25.487；VQA 基线 0.522，Decoupled 为 0.521 / 0.513 / 0.532，Full-LoRA 为 0.453 / 0.427 / 0.550。VBench 的质量指标是这组里最关键的结果——主体一致性、背景一致性、运动平滑度、美学质量在两种推理模式下都与基线几乎相同，说明新控制的注入没有引入伪影也没有削弱底模的生成质量。唯一明显偏离的是快门 Full-LoRA 下的 Dynamic Degree（0.688 vs 基线 0.427），Decoupled 把它拉回 0.469。</p><p>第三组是谱分析。入侵维度检查显示合成训练几乎不产生漂移，真实数据训练在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1389em;">W</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:-0.1389em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 的浅层与中层就出现大量高相似度 intruder 并在深层聚集成簇。有效秩分析显示联合训练模型的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">cond</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 呈现清晰肘部、有效秩为 1；而 adapter-only 模型的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">cond</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 高秩且衰减缓慢、形态与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">y</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">text</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 相似。作者把后者的失败命名为「Bulldozer Effect」：adapter-only 的条件信号不仅高秩，幅值也大得多，且与 backbone 的内容空间正交——它把记住的内容表示在一个空闲子空间里，推理时这个强信号直接推平文本信号，输出被训练场景特征主导。</p><p>控制质量方面，5 点扫描（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">c</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">−</span><span class="mord">1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">−</span><span class="mord">0.5</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.5</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">}</span></span></span></span>）下 Spearman 秩相关的中位数 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathnormal">ρ</span><span class="mord">∣</span></span></span></span> 三个控制都是 1.00，方向正确率 100%，均值分别为快门 0.987（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">15</span></span></span></span>）、光圈 0.912（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">17</span></span></span></span>）、色温 1.000（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">14</span></span></span></span>）。超出训练区间的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">c</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">±</span><span class="mord">1.5</span></span></span></span> 仍能平滑外推，效应继续增强而 prompt 保真度不损。与文本 prompt 控制对比时，WAN 2.1 表现出明显的语义纠缠：要求改快门时它把玻璃门画成金属门，要求改色温时它把「温度」理解成天气而给场景加雪。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p>五句话版：往预训练 T2V 里加物理相机控制（快门、光圈、色温）不需要真实数据，稀疏低保真的几何原语合成数据反而更好。架构上用一路与文本并行的 cross-attention adapter 注入归一化标量条件（只插最深三分之一 block），同时让一个覆盖全部 block 的 backbone LoRA 吸收合成域偏移，推理时丢掉浅层三分之二的 LoRA 恢复原始先验。金字塔采样把训练集压到 150 个样本，比穷举小 30 倍。照片级数据会引发恶性的灾难性遗忘——FEP 测到的漂移速率高、SVP 的 X-CLIP 与 VQA 崩塌、权重谱上出现大量入侵维度、生成结果向训练场景复制。谱分析进一步证明联合训练学到的条件信号有效秩为 1（学到效应本身），而 adapter-only 训练学到高秩信号并产生「Bulldozer Effect」把文本信号推平。</p><p>三句话版：foundation 模型已经知道什么是运动模糊，微调只需给它一个旋钮，所以数据只要在控制轴上干净变化即可，内容越简单越好。让 LoRA 吸收域偏移、adapter 专学效应，再在推理时丢掉多余的 LoRA，就能拿到连续可控且不损伤底模的新控制轴。论文还顺带贡献了一套量化「数据复杂度对 backbone 的破坏程度」的诊断工具，这在现有评测体系里是空白。</p><p>一句话版：用最简陋的合成数据教模型调相机参数，比用漂亮的真实数据更好，因为漂亮的数据会让它忘掉本来会的东西。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最致命的假设是：<strong>目标控制轴对应的物理效应已经完整存在于预训练先验中，微调只需要提供一个索引</strong>。这是「Less is More」全部逻辑的支点。快门、光圈、色温三者恰好都满足——它们是全局的、低维的、且在自然视频语料里以极高频率出现，模型必然见过大量运动模糊和浅景深镜头。</p><p>一旦这个前提不成立，整套方法会直接失效而非缓慢退化。设想一个预训练分布里罕见的控制轴：特定的偏振效果、非标准焦外形状、或某种预训练视频中几乎不出现的材质响应。此时 adapter 无法「索引」出不存在的先验，只能从几何原语数据里学，而几何原语数据恰恰不包含任何真实世界的外观信息——模型要么学不会，要么被迫记住原语内容，退化成论文自己描述的 Bulldozer Effect。</p><p>论文提供的证据全部来自三个「先验充足」的控制，缺的是一个负例：在一个预训练分布中稀缺的效应上，简单合成数据是否依然优于真实数据。作者在结论里提出可扩展到深度、位姿等空间控制，但明确标注为未来工作，且这些同样是预训练中高频出现的属性，不构成对该假设的检验。另一处相关证据反而暗示边界存在——附录指出，只用一个训练场景时 backbone 保真度仍好但<strong>条件效果明显变弱</strong>，说明数据多样性并非完全无关，学习效应本身仍需要一定的证据量。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做、且不需要 14B 全量训练的最小验证针对 §9。把 backbone 换成一个更小的开源 T2V（如 Wan2.1-T2V-1.3B），只做色温这一个控制轴（它的数据构造最便宜，纯 2D 白平衡变换，不需要 Blender）。</p><p>实现三个训练配置，各约 150 个样本、相同步数：(a) 论文的几何原语合成数据；(b) 照片级单场景数据；(c) 关键对照——一个<strong>预训练分布中稀缺</strong>的控制轴，例如「径向色差强度」（用简单的通道级径向位移合成，自然视频里几乎不出现）。评测只需要 FEP 这一半：SSF 与 SS-FD 只做单步去噪、4 帧、固定种子，成本极低，用 VBench 的 800 条 prompt 跑。</p><p>测量：三者的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">drift</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，以及最终的控制单调性（对每条 prompt 做 5 点扫描，用一个简单的图像代理量——色温用全局暖冷色偏统计，色差用通道边缘错位量——算 Spearman <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathnormal">ρ</span><span class="mord">∣</span></span></span></span>）。判据：若 (c) 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">drift</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 与 (a) 相当但 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathnormal">ρ</span><span class="mord">∣</span></span></span></span> 显著低于 (a)，说明简单合成数据只在「先验已存在」时有效，论文的适用边界被划出来了；若 (c) 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord mathnormal">ρ</span><span class="mord">∣</span></span></span></span> 也接近 1，说明 adapter 确实能从零学会新效应，论文的 claim 比自己声称的还强。这个实验只训三个小模型加轻量评测，一周内可完成。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>替代解释攻击：论文把「合成数据更好」归因于低复杂度防止了灾难性遗忘，但 Group 1 的对照设计存在一个未被控制的混杂变量——<strong>合成数据集在效应轴上是完美对齐的，照片级数据集不是</strong>。合成数据的构造方式保证了同一场景下所有条件取值共享完全相同的轨迹、几何、光照，唯一变化的就是目标效应；而照片级快门数据来自对 240fps 视频做时域累加，不同累加窗口对应的内容其实并不完全相同（累加窗口越长，覆盖的动作阶段越多），照片级光圈数据用 BokehMe 后处理引入了自身的渲染伪影。</p><p>如果真正起作用的是<strong>条件对齐度</strong>而非<strong>内容简单度</strong>，那么论文的核心建议就该改写：微调数据集应当追求条件对齐，而简单只是实现对齐的一种便宜手段，不是本质。这不是吹毛求疵——两种解释导出的实践指导完全不同。前者说「放弃真实感」，后者说「保留真实感但用严格受控的采集或渲染」，后者显然更有价值也更可行（用 Blender 渲照片级但条件严格对齐的场景完全可行）。</p><p>具体实验：构造第三个数据集——<strong>照片级但条件完美对齐</strong>。用 Blender 渲染一个复杂真实感场景（含材质、纹理、全局光照），保持相机位姿、物体几何、光照完全固定，只改 f 值渲出 7 个光圈条件。用它训练，与论文的两个配置一起测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">drift</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>、X-CLIP、VQA 与入侵维度数。若这个配置的表现接近合成组（低漂移、无坍缩），则「简单」不是关键，「对齐」才是，论文的解释框架需要修正；若它仍然像照片级组一样坍缩，则论文关于内容复杂度本身有害的 claim 得到强有力的独立支持。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>驱动局限：论文把每个控制轴当作独立的适配任务，三个参数各训一套 adapter 与 LoRA。作者在结论里把「统一模型从单一联合控制向量中解耦多个参数」列为未来工作。但更深的局限在于，当前框架里「什么可以被 coax 出来」完全靠人工猜测——研究者先决定要做快门、光圈、色温，再验证它们能被学出来。没有任何方法能事先告诉我们，一个给定的 foundation 模型的潜空间里<strong>还藏着哪些可分离的控制轴</strong>。</p><p>新的 framing：把可控性从「注入控制」翻转成「发现控制」。论文自己提供了关键线索——成功的适配会产生有效秩为 1 的条件信号。这个性质可以反过来用作搜索目标：在潜表示中寻找那些低维、与内容信号近乎正交、且沿其移动会引起一致语义变化的方向。这不是加一个模块，而是把可控生成的研究流程从「设计—验证」改成「发现—命名」。</p><p>可借鉴的相邻领域工具来自 GAN 潜空间的无监督方向发现（GANSpace 的 PCA、SeFa 的闭式分解、以及基于 Jacobian 的方法），以及机制可解释性里的稀疏自编码器——后者恰恰擅长从高维激活中分离出稀疏、单义的特征方向，而「单义」正是论文所说的「解耦」在表示层面的对应物。</p><p>第一个实验：不训练任何 adapter。在冻结的 Wan2.1 上，对一批多样 prompt 收集深层 DiT block 的 cross-attention 输出激活，训一个稀疏自编码器分解成若干单义方向。对排名靠前的若干方向，逐个沿其做小幅扰动并完整生成视频，用一组廉价的图像代理量（Laplacian 方差测锐度、背景锐度测散景、全局色偏测色温、光流幅值测运动量）批量测量每个方向引起的效应。测量两件事：一是这些方向中有多少能对应到某个可命名的物理或摄影属性，二是论文已经用数据学出来的三个控制（快门、光圈、色温）是否恰好落在这些自动发现的方向附近。若第二点成立，就说明这三个控制其实一直「在那儿」，论文的合成数据只是找到了它们的坐标——而稀疏自编码器可以免去数据构造这一步，直接把整个可控轴清单列出来。</p>',57)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
